declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$VOD$q$,$q$Vodafone Group$q$,null,null,true,false,array[$q$LSE$q$,$q$US$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$1&1$q$,$q$public_company$q$),($q$AST SpaceMobile$q$,$q$public_company$q$),($q$Alphabet$q$,$q$public_company$q$),($q$Altice Luxembourg$q$,$q$private_company$q$),($q$Amazon$q$,$q$public_company$q$),($q$BlackRock$q$,$q$public_company$q$),($q$CK Hutchison$q$,$q$public_company$q$),($q$Community Fibre$q$,$q$private_company$q$),($q$Digi Romania$q$,$q$public_company$q$),($q$Hutchison Telecommunications (Australia)$q$,$q$public_company$q$),($q$IBM$q$,$q$public_company$q$),($q$Idea Group$q$,$q$public_company$q$),($q$Indus Towers$q$,$q$public_company$q$),($q$Liberty Global$q$,$q$public_company$q$),($q$Maziv$q$,$q$private_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$Norges Bank$q$,$q$institution$q$),($q$OXG$q$,$q$private_company$q$),($q$Oak Holdings$q$,$q$private_company$q$),($q$Oak Holdings 1 GmbH$q$,$q$private_company$q$),($q$Recommerce$q$,$q$private_company$q$),($q$SIRO$q$,$q$private_company$q$),($q$Safaricom$q$,$q$public_company$q$),($q$Skaylink$q$,$q$private_company$q$),($q$TPG Telecom$q$,$q$public_company$q$),($q$Telecommunication Infrastructure Company of Iran$q$,$q$institution$q$),($q$Telekom Romania$q$,$q$private_company$q$),($q$Telekom Romania Mobile Communications$q$,$q$private_company$q$),($q$Telenor$q$,$q$public_company$q$),($q$Three UK$q$,$q$private_company$q$),($q$Vantage Towers$q$,$q$private_company$q$),($q$Virgin Media O2$q$,$q$private_company$q$),($q$Vodafone Idea$q$,$q$public_company$q$),($q$VodafoneZiggo$q$,$q$private_company$q$),($q$Zegona$q$,$q$public_company$q$),($q$e&$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Amazon Leo agreement signed to extend mobile coverage across Europe and Africa$q$),(2,$q$Amounts are primarily in relation to leases of tower space from Oak Holdings 1 GmbH.$q$),(3,$q$As per the terms of our strategic relationship agreement with e&, Hatem Dowidar does not receive a fee for this role.$q$),(4,$q$At 31 March 2026 the Group has committed to enter into future lease contracts with future undiscounted lease payments of €2,349 million (31 March 2025: €1,464 million) which includes €1,386 million (31 March 2025: €1,102 million) of commitments to Vantage Towers A.G., a subsidiary of the Group’s joint arrangement Oak Holdings 1 GmbH, for tower leases which predominantly have terms of eight years from the date on which the towers are made available for use.$q$),(5,$q$During the financial year ended 31 March 2026, Vodafone Global Network Limited (VGN) continued to be a member of a consortium including Telecommunication Infrastructure Company of Iran (‘TIC’) (an entity controlled by the government of Iran) that has built a high-speed cable network from a landing point in Oman to Germany.$q$),(6,$q$Emirates Telecommunications Group Company PJSC (‘e&’) 3,944,743,685 BlackRock, Inc. 1,743,626,604 Norges Bank 803,179,853 Shareholding1 17.005026% 6.50% 3.0004%$q$),(7,$q$Equity securities include an investment in AST SpaceMobile, Inc (‘AST’) of €1,044 million (2025: €306 million) which is measured at fair value through other comprehensive income.$q$),(8,$q$Following approval from the UK Competition and Markets Authority (CMA) for Vodafone UK’s merger with Three UK and launching the VodafoneThree Joint Venture in June 2025, we reviewed our five-year investment strategies, execution plans, and necessary governance required to integrate the network and IT estates of both entities.$q$),(9,$q$Following receipt of the cash return described above, the Group contributed €188 million into the holding structure to reduce borrowings in that structure, with Hutchison Telecommunications (Australia) Limited contributing an equal amount.$q$),(10,$q$Following the merger of Vodafone UK with Three UK during the year, information is not yet available for Three UK employees.$q$),(11,$q$For example, we partnered with Recommerce in Germany to offer our customers the possibility to purchase refurbished devices, enabling them to participate in the circular economy.$q$),(12,$q$In December 2025, Vodacom completed the acquisition of a stake in Maziv.$q$),(13,$q$In December 2025, the Group announced that the Vodacom Group has agreed to increase its stake in Safaricom to 55%.$q$),(14,$q$In December 2025, the Group completed the acquisition of Skaylink GmbH.$q$),(15,$q$In December 2025, we completed the acquisition of Skaylink, a cloud, digital transformation and security specialist.$q$),(16,$q$In June 2025, we announced a wholesale strategic agreement with Community Fibre in London.$q$),(17,$q$In March 2023, the Group entered into an agreement with Altice Luxembourg S.A. to create a joint venture, OXG Glasfaser Beteiligungs GmbH (‘OXG’), with 50.0% shareholding held by each shareholder.$q$),(18,$q$In October 2025, we concluded the acquisition of Telekom Romania, increasing our scale in the county.$q$),(19,$q$In September 2025, the Group completed the acquisition of Telekom Romania and its post-paid customer base.$q$),(20,$q$In the comparative year, on 22 July 2024, the Group announced the sale of a further 10.3% stake in Oak Holdings 1 GmbH (‘Oak Holdings’), the partnership that co-controls Vantage Towers, for €1,336 million, leaving the Group’s retained interest at 50.0%.$q$),(21,$q$In the prior year, equity securities with a level 3 classification basis included an investment in Zegona shares (2025: €937 million).$q$),(22,$q$Likewise, through our procurement partnership with Telenor, we have jointly strengthened our approach to supplier environmental criteria during both selection and contractual processes to accelerate the development of their environmental programmes.$q$),(23,$q$Management determined the recoverable amount of the Group’s investment in Indus Towers on a fair value less costs to sell basis.$q$),(24,$q$On 1 October 2025, we completed the acquisition of assets of Telekom Romania Mobile Communications S.A for €30 million, strengthening our position in the market.$q$),(25,$q$On 17 December 2025, following the announcement on 30 October 2025, Vodafone Group announced that it has completed the acquisition of 100% of Skaylink GmbH for a total consideration of €175 million.$q$),(26,$q$On 17 December 2025, the Group announced it had completed the acquisition of Cloudforce 1 GmbH (‘Skaylink’) for a total cash consideration of €175 million.$q$),(27,$q$On 17 December 2025, we announced the acquisition of Skaylink, a cloud, digital transformation and security specialist.$q$),(28,$q$On 18 February 2026, Vodafone Group Plc announced that it agreed to sell its 50% interest in VodafoneZiggo Group Holding B.V. (‘VodafoneZiggo’) to Liberty Global plc (‘Liberty Global’) for €1.0 billion in cash and a 10% shareholding in a soon-to-be-formed Benelux entity (‘Ziggo Group’), which will own 100% of both VodafoneZiggo and Liberty Global’s Belgian subsidiary, Telenet Group Holding (‘Telenet’).$q$),(29,$q$On 19 September 2025, Vodafone Romania S.A. and Digi Romania S.A. (‘Digi’) entered into binding agreements with Hellenic Telecommunications Organization S.A. (‘OTE’) to acquire separate parts of OTE’s subsidiary, Telekom Romania Mobile Communications S.A. (‘TKRM’).$q$),(30,$q$On 2 December, Vodacom (Pty) Limited (‘Vodacom’) acquired a 30% interest in Maziv Proprietary Limited (‘Maziv’) for €620 million, of which €410 million was settled in cash and included in Purchase of interests in associates and joint ventures in the Consolidated statement of cashflows.$q$),(31,$q$On 31 May 2025, the Group and CK Hutchison Group Telecom Holdings Limited (‘CKHGT’), a wholly owned subsidiary of CK Hutchison Holdings Limited (‘Hutchison’), transferred their UK telecommunication businesses, respectively Vodafone Limited (‘Vodafone UK’) and Hutchison 3G UK Holdings Limited (‘Three UK’), into VodafoneThree Holdings Limited (‘VTHL’).$q$),(32,$q$On 5 May 2026, we announced our agreement for the buyout of CK Hutchison Group Telecom Holding Limited from the VodafoneThree joint venture for £4.3 billion (€4.9 billion) via a cancellation of shares.$q$),(33,$q$Our partnership with Microsoft further gives us the potential to access new technologies such as Generative Artificial Intelligence (‘Gen AI’) and to deploy these at scale for IoT.$q$),(34,$q$Principally comprises Vodafone Group Plc’s guarantee of the Group’s share in a multicurrency loan facility, amounting to US$0.5 billion and €0.6 billion (2025: US$1.0 billion and €0.6 billion), which forms part of its overall joint venture investment in TPG Telecom Ltd.$q$),(35,$q$Safaricom Associate (Kenya) – 27.8% ownership$q$),(36,$q$Safaricom PLC2 TPG Telecom Limited3 Maziv Proprietary Limited Indus Towers Limited Principal activity Network operator Network operator Network infrastructure Network infrastructure Country of incorporation or registration Kenya Australia South Africa India Percentage shareholding1 2026 39.9 23.7 30.0 – Percentage shareholding1 2025 39.9 25.1 – –$q$),(37,$q$TPG Telecom Limited Associate (Australia) – 23.7% ownership$q$),(38,$q$The Board approved Vodacom’s purchase of an additional 15% stake in Safaricom, increasing Vodacom’s shareholding and giving the Group greater strategic and operational alignment across Kenya and the broader region.$q$),(39,$q$The Board approved Vodafone’s acquisition of Skaylink, a European cloud and digital transformation specialist.$q$),(40,$q$The Board approved the acquisition of Telekom Romania’s fixed line operations (now Vodafone Romania), a transaction that strengthens Vodafone’s converged capabilities in the Romanian market and supports the Group’s European fixed mobile strategy.$q$),(41,$q$The Group has set aside 3,280 million of Vodafone Group's shares in VIL for VIL’s benefit.$q$),(42,$q$The Group owns an equivalent economic interest of 23.7%, via an 11% direct stake in TPG and a 13% indirect stake, held through a 50:50 joint venture with CK Hutchison.$q$),(43,$q$The Group’s ability to realise expected benefits from acquisitions, partnerships, joint ventures, associates, franchises, brand licences, platform sharing, or other arrangements with third parties, including the combination of Vodafone’s UK business with Three UK, the mobile network sharing agreement with Virgin Media O2, and the Group’s strategic partnerships with Microsoft and Google;$q$),(44,$q$The Group’s shareholding in Vodafone Idea Limited was subsequently diluted to 16.1% in April 2025.$q$),(45,$q$The amount in 2026 primarily derives from gains on our investment in AST SpaceMobile, Inc and on cashflow hedges.$q$),(46,$q$The assessment of the capacity of the Group to remain viable after consideration of future cash flows, including the impact of the agreement for the buyout of CK Hutchison Group Telecom Holding Limited’s 49% interest in VodafoneThree Holdings Limited (‘VodafoneThree’) and Vodacom’s acquisition in Safaricom;$q$),(47,$q$The combined business, named VodafoneThree, is 51% owned by Vodafone and 49% by CKHGT.$q$),(48,$q$The non-cash consideration comprises an investment in Zegona shares with a fair value of €807 million at the transaction date.$q$),(49,$q$The shares issued by TPG resulted in Vodafone’s and Hutchison Telecommunications (Australia) Limited’s respective economic interest decreasing to 23.7%, with the remaining 52.6% listed as free float on the ASX.$q$),(50,$q$Through our joint research with IBM, we have developed a risk-based approach to mitigate the risks of existing cryptography.$q$),(51,$q$Through our wholesale partnerships, including our fibre joint venture, SIRO, we now cover 1.9 million households in Ireland with our gigabit speeds.$q$),(52,$q$Through strategic investments in the latest technologies such as our OXG joint venture in Germany and wholesale partnerships, our Gigabit-capable broadband now reaches 66 million European homes, an increase of 6 million in FY26.$q$),(53,$q$VIL undertook a conversion of debt due to the Government of India during April 2025, resulting in the Group’s interest in VIL reducing to 16.1%.$q$),(54,$q$Vantage Towers Joint Venture – 44.7% ownership$q$),(55,$q$Vodacom will acquire 15% from the Government of Kenya (the ‘GOK’) for a cash consideration of €1.36 billion (KES 204 billion), and 5% from Vodafone for a cash consideration of €0.45 billion (KES 68 billion).$q$),(56,$q$Vodafone Group Plc became the ultimate parent of Hutchison 3G UK Holdings Limited (“Three UK”), following the acquisition of Three UK on 31 May 2025.$q$),(57,$q$Vodafone acquired TKRM and its post-paid customer base for €30 million (before standard closing adjustments), while Digi has agreed to acquire its pre-paid customer business.$q$),(58,$q$VodafoneZiggo Joint Venture (Netherlands) – 50.0% ownership$q$),(59,$q$We are partnering with AST SpaceMobile to enable D2D satellite connectivity for secure and resilient digital communications in any location at any time.$q$),(60,$q$We can deploy GenAI at speed and scale through partnerships with Google and Microsoft, enhancing TOBi and enabling more personalised experiences across customer touchpoints.$q$),(61,$q$We now have more than 12 million 1&1 customers using our nationwide 5G network and revenue contribution reached full run-rate in Q4.$q$),(62,$q$the Implementation Agreement dated 20 March 2017, as amended, relating to the combination of the Indian mobile telecommunications businesses of Vodafone Group and Idea Group as detailed in note 27 ‘Acquisitions and disposals’ to the consolidated financial statements.$q$),(63,$q$the Share Purchase Agreement dated 3 December 2025 between Vodafone Kenya Limited and the Government of the Republic of Kenya relating to the acquisition of 6,009,814,200 ordinary shares in Safaricom PLC from the Government of the Republic of Kenya by Vodafone Kenya Limited, as amended on 26 February 2026 and 22 April 2026.$q$),(64,$q$the Shareholder Agreement dated 31 May 2025 between Vodafone International Operations Limited, Vodafone Group Plc, Brilliant Design (BVI) Limited, CK Hutchison Group Telecom Holdings Limited and Vodafone UK Trading Holdings Limited relating to the merger of Vodafone UK and Three UK.$q$),(65,$q$€410 million in relation to the acquisition of a 30% interest in Maziv Proprietary Limited$q$);
